#include "engine.hpp"
#include <iostream>
#include <cmath>
using namespace uaa;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
int main(int argc,char** argv){try{Engine e(argv[1],argv[2]);e.createBase("AIR OPS",0,0);e.state["nextUfo"]=100000.;e.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.},{"hull",100.},{"spawned",5.},{"expires",720.},{"environment","AIR"}});check(e.alertLevel()==0,"Unknown UFO does not leak into alert level");auto c=e.advanceUntilUfoContact(168);check(c.size()==1&&e.state["hours"]==5.,"Fast time stops exactly at first radar detection rather than requested end");check(e.alertLevel()==2,"Contact near base is red");e.acknowledgeUfoContacts(c);check(e.advanceUntilUfoContact(1).empty()&&e.state["hours"]==6.,"Same acknowledged contact cannot repeatedly stop time");e.save(1);Engine reload(argv[1],argv[2]);check(reload.load(1).ok&&reload.unacknowledgedUfoContacts().empty(),"Acknowledgement persists across save/load");e.state["ufos"][0]["lon"]=18.;e.processRadarContacts(6,6);check(e.alertLevel()==1,"Single remote observed contact is orange");e.state["ufos"]=Json::array();check(e.alertLevel()==0,"No active observed contacts is green");
 Engine sat(argv[1],std::filesystem::path(argv[2])/"satellite");sat.createBase("SATELLITE",0,0);for(auto& b:sat.state["bases"][0]["buildings"])if(b["id"]=="radar")b["ready"]=1000.;sat.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.},{"hull",100.},{"spawned",0.},{"expires",720.},{"environment","AIR"}});sat.recordSatelliteScan(0,0,0,"AIR",900,1);check(sat.advanceUntilUfoContact(24).size()==1&&sat.state["hours"]==0.,"Satellite observation also raises an immediate report without advancing time");
 e.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.},{"hull",100.},{"spawned",0.},{"expires",48.},{"environment","AIR"}});auto untouched=e.state;check(e.interceptionReadiness(0,0).ok&&e.state==untouched,"Readiness query must not start combat or consume fuel");e.state["craft"][0]["fuel"]=0.;untouched=e.state;check(!e.interceptionReadiness(0,0).ok&&!e.intercept(0,0).ok&&e.state==untouched,"Picker and dispatch reject the same unready fighter without side effects");e.state["craft"][0]["fuel"]=100.;e.state["ufos"]=Json::array();
 auto f=e.fighterFuel(0);check(f["capacityLitres"]==4500.&&f["rangeKm"]==2200.&&f["combatRadiusKm"]==825.,"Modern baseline fuel capacity, range and safe combat radius");check(e.setAircraftModule(0,"system","FUEL_TANK").ok,"External tank is a selectable fighter system");f=e.fighterFuel(0);check(std::abs(f["fuelLitres"].get<double>()-4500)<1e-6&&f["capacityLitres"]==6600.&&f["rangeKm"]==3200.,"Installing tank adds capacity without creating fuel");e.state["craft"][0]["fuel"]=100.;check(e.fighterFuel(0)["combatRadiusKm"]==1200.,"Full external tank increases safe combat radius");e.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",9.},{"hull",100.},{"spawned",0.},{"expires",720.},{"environment","AIR"}});auto saved=e.state;check(e.setAircraftModule(0,"system","AUX_RADAR").ok,"Other system replaces tank");e.state["craft"][0]["fuel"]=100.;auto before=e.state;check(!e.intercept(0,0).ok&&e.state==before,"Internal tank cannot launch beyond return-safe combat radius");e.state=saved;check(e.intercept(0,0).ok&&e.state["craft"][0]["fuel"].get<double>()>=15.,"External tank enables longer interception and preserves reserve after round trip");e.save(2);check(reload.load(2).ok&&reload.aircraftModule(0,"system")=="FUEL_TANK","External tank survives validated save/load");Engine life(argv[1],std::filesystem::path(argv[2])/"lifecycle");life.createBase("LIFECYCLE",0,0);life.state["nextUfo"]=100000.;life.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.},{"hull",100.},{"spawned",0.},{"expires",720.},{"environment","AIR"},{"landingAt",1.},{"takeoffAt",100.},{"surfaceEnvironment","LAND"}});life.advance(2);check(life.state["ufos"][0]["takeoffAt"]==19.&&life.state["ufos"][0]["expires"]==48.&&life.state["ufos"][0]["hull"]==100.&&life.state["ufoSites"].empty(),"Natural landing lasts at most 18 hours and preserves intact UFO rather than creating wreckage");life.advance(17);check(life.state["ufos"][0]["environment"]=="AIR","Landed UFO takes off at the 18-hour limit");life.advance(29);check(life.state["ufos"].empty()&&life.state["ufoSites"].empty(),"Total active stay ends at 48 hours without creating a wreck");life.recordUfoCrashSite({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.}});check(life.state["ufoSites"][0]["kind"]=="CRASH","Shot-down UFO has a distinct wreck record");Engine legacy(argv[1],std::filesystem::path(argv[2])/"legacy-life");legacy.createBase("LEGACY",0,0);legacy.state["nextUfo"]=100000.;legacy.state["hours"]=20.;legacy.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.},{"hull",100.},{"spawned",0.},{"expires",720.},{"environment","LAND"},{"landingAt",1.},{"takeoffAt",100.},{"surfaceEnvironment","LAND"}});legacy.save(1);Engine migrated(argv[1],std::filesystem::path(argv[2])/"legacy-life");check(migrated.load(1).ok&&migrated.state["ufos"][0]["expires"]==48.&&migrated.state["ufos"][0]["takeoffAt"]==19.&&migrated.state["ufos"][0]["environment"]=="AIR","Old saved UFOs also obey new duration limits");
 std::cout<<"PASS: observed alert levels, exact first detection stop, acknowledgement, fuel capacity, modern ranges, round trip reserve, module selection, persistence, intact landings up to 18 h and total stay up to 48 h\n";return 0;}catch(const std::exception& ex){std::cerr<<ex.what()<<'\n';return 1;}}
